package com.campusconnect.model;
import java.time.LocalDateTime;
public class Complaint { private int id,studentId; private String studentName,category,description,priority,status,resolutionRemarks; private LocalDateTime createdAt;
 public Complaint(){} public int getId(){return id;} public void setId(int v){id=v;} public int getStudentId(){return studentId;} public void setStudentId(int v){studentId=v;} public String getStudentName(){return studentName;} public void setStudentName(String v){studentName=v;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getPriority(){return priority;} public void setPriority(String v){priority=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getResolutionRemarks(){return resolutionRemarks;} public void setResolutionRemarks(String v){resolutionRemarks=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}}
